<?php
namespace Delnavazan\Platform\Core\Application; use Delnavazan\Platform\Core\Infrastructure\Repository\StudentRepository;
final class StudentService { public function create(array $d):int{if(!current_user_can('dzn_manage_students'))throw new \RuntimeException('Unauthorized');$d['status']=Normalizer::one($d['status']??'active',['active','inactive'],'student state');foreach(['first_name','last_name','city']as$f)$d[$f]=Normalizer::text($d[$f]??null);$d['display_name']=Normalizer::text($d['display_name']??'',191,true);$d['email']=Normalizer::email($d['email']??null);foreach(['phone','whatsapp_phone']as$f)$d[$f]=Normalizer::phone($d[$f]??null);$d['country_code']=Normalizer::country($d['country_code']??null);$d['timezone']=Normalizer::timezone($d['timezone']??null);$d['timezone_source']=Normalizer::timezoneSource($d['timezone_source']??null);$d['locale']=Normalizer::locale($d['locale']??null);$d['calendar_preference']=Normalizer::one($d['calendar_preference']??'auto',['auto','gregorian','persian'],'calendar');$d['wordpress_user_id']=Normalizer::id($d['wordpress_user_id']??null,false);return Creator::create(new StudentRepository,$d,'DZN-STU-');} }
